from thefuck.shells import shell
from thefuck.specific.git import git_support
from thefuck.utils import eager
import re


@git_support
def match(command):
    if 'branch' not in command.script:
        return False
    return ("fatal: A branch named '" in command.stderr
            and command.stderr.find(" already exists.") != -1)


@git_support
@eager
def get_new_command(command):
    pattern = r"fatal: A branch named '([^']*)' already exists."
    extracted_branch = re.findall(pattern, command.stderr)[0]
    template_groups = [
        ('git branch -d {0}', 'git branch {0}'),
        ('git branch -D {0}', 'git branch {0}'),
        ('git checkout {0}',
    ]
    idx = 0
    while idx < len(template_groups):
        yield shell.and_(*template_groups[idx]).format(extracted_branch)
        idx += 1
